INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422590, 16157, 'The Guardian', 'en', 'US Federal Reserve’s Kevin Warsh gears up for key Jackson Hole conference as inflation fears mount', 'https://www.theguardian.com/business/live/2026/aug/28/us-federal-reserve-kevin-warsh-jackson-hole-conference-inflation-economy-ftse-stock-markets-latest-updates', 'Rolling coverage of the latest events in global financial markets, the economy and major corporate moves In the metals market, supply fears have pushed the zinc price up to a four-year high. Zinc, which is used to galvanise steel, hit $3,955 a metric tonne this morning, its highest since May 2022. LME [zinc] inventories have been drawn sharply lower, mine and smelter disruptions have restricted refined availability, and supply outside China has become notably tight. With consumers facing a thinner pool of immediately available units, relatively modest buying has produced a larger price respons', 'https://i.guim.co.uk/img/media/a4a8eddd16bbb988095e15a40e1535097cc89ab5/0_47_2985_2388/master/2985.jpg?width=140&quality=85&auto=format&fit=max&s=ce494085bfbaa0f90b342492d6a84075', '2026-08-28T12:20:36+00:00', '2026-08-28T12:49:07.291106'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
